public class Solution {
  /**
   * 贪心切批：按到达顺序尽量往当前批次里塞，一旦"再加一条就破预算"就 flush。
   * 因为可行性对批次长度单调（越塞越不可行），贪心即最优；O(n) 时间、O(1) 额外空间。
   */
  public static int minFlushBatches(int[] recordBytes, int maxBatchBytes, int maxBatchRecords) {
    if (maxBatchBytes <= 0 || maxBatchRecords <= 0) {
      throw new IllegalArgumentException("bad batch policy");
    }
    if (recordBytes == null) {
      throw new IllegalArgumentException("recordBytes is null");
    }
    long maxBytes = maxBatchBytes & 0xffffffffL;
    for (int b : recordBytes) {
      if (b < 0) throw new IllegalArgumentException("negative record size");
      if ((b & 0xffffffffL) > maxBytes) return -1; // 单条超预算：业务失败
    }
    int batches = 0;
    int curCount = 0;
    long curBytes = 0L;
    for (int b : recordBytes) {
      boolean byteBreak = curBytes + b > maxBytes;      // long 域比较，杜绝 int 溢出
      boolean countBreak = curCount + 1 > maxBatchRecords;
      if (curCount > 0 && (byteBreak || countBreak)) {
        batches++;
        curCount = 0;
        curBytes = 0L;
      }
      curCount++;
      curBytes += b;
    }
    if (curCount > 0) batches++;
    return batches;
  }
}

runner.naiveSolution:
public class Solution {
  // 只看条数预算（生产里最常见的"我们的 sink 只配了 maxRecords"版本）
  public static int minFlushBatches(int[] recordBytes, int maxBatchBytes, int maxBatchRecords) {
    if (maxBatchBytes <= 0 || maxBatchRecords <= 0) {
      throw new IllegalArgumentException("bad batch policy");
    }
    if (recordBytes == null || recordBytes.length == 0) return 0;
    for (int b : recordBytes) {
      if (b < 0) throw new IllegalArgumentException("negative record size");
    }
    return (recordBytes.length + maxBatchRecords - 1) / maxBatchRecords;
  }
}
